using UrlShortener.Core;
using Xunit;

namespace UrlShortener.Tests;

public class LinkTests
{
    // --- existing behavior (must keep passing) ---

    [Fact]
    public void Create_stores_and_returns_a_resolvable_link()
    {
        var store = new InMemoryLinkStore();
        var link = store.Create("https://example.com/page");
        Assert.Equal("https://example.com/page", store.Get(link.Code)?.TargetUrl);
    }

    [Fact]
    public void Unknown_code_resolves_to_null()
    {
        Assert.Null(new InMemoryLinkStore().Get("missing"));
    }

    [Theory]
    [InlineData("https://a.com", true)]
    [InlineData("http://a.com", true)]
    [InlineData("ftp://a.com", false)]
    [InlineData("not-a-url", false)]
    [InlineData("", false)]
    public void Validates_absolute_http_urls(string url, bool expected)
    {
        Assert.Equal(expected, UrlValidator.IsValid(url));
    }

    [Fact]
    public void Codes_are_url_safe_and_sized()
    {
        var code = ShortCode.Generate();
        Assert.InRange(code.Length, 6, 8);
        Assert.Matches("^[A-Za-z0-9]+$", code);
    }

    [Fact]
    public void Codes_are_unique_across_links()
    {
        var store = new InMemoryLinkStore();
        var a = store.Create("https://a.com");
        var b = store.Create("https://b.com");
        Assert.NotEqual(a.Code, b.Code);
    }

    // --- new: expiring links ---

    [Fact]
    public void Link_without_expiry_never_expires()
    {
        var link = new InMemoryLinkStore().Create("https://a.com");
        Assert.False(link.IsExpired(DateTimeOffset.UtcNow.AddYears(10)));
    }

    [Fact]
    public void Active_link_with_future_expiry_is_not_expired()
    {
        var link = new InMemoryLinkStore().Create("https://a.com", DateTimeOffset.UtcNow.AddHours(1));
        Assert.False(link.IsExpired(DateTimeOffset.UtcNow));
    }

    [Fact]
    public void Link_past_its_expiry_is_expired()
    {
        var link = new InMemoryLinkStore().Create("https://a.com", DateTimeOffset.UtcNow.AddMinutes(-1));
        Assert.True(link.IsExpired(DateTimeOffset.UtcNow));
    }

    // --- new: click analytics ---

    [Fact]
    public void Recording_clicks_increments_the_count_and_timestamp()
    {
        var store = new InMemoryLinkStore();
        var link = store.Create("https://a.com");
        var t = DateTimeOffset.UtcNow;
        store.RecordClick(link.Code, t);
        store.RecordClick(link.Code, t.AddSeconds(5));

        var stats = store.GetStats(link.Code);
        Assert.NotNull(stats);
        Assert.Equal(2, stats!.ClickCount);
        Assert.Equal(t.AddSeconds(5), stats.LastClickedAt);
    }

    [Fact]
    public void Stats_for_unknown_code_is_null()
    {
        Assert.Null(new InMemoryLinkStore().GetStats("missing"));
    }
}
